using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class BasicActorOperations
{
    private readonly ModelNaturalRender _naturalRender=new();private readonly FogMotionRenderOperations _fogMotion=new();private readonly GrowthInstanceRuntime _growthInstances=new();
    public void apply_environment(Node3D owner,Variant value){var data=Resolve(owner,value);var world=runtime_world(owner,true);if(world==null)return;if(data==null||data.Get("type_id").AsString()!="environment"){restore_environment(owner);return;}var environment=owner.Get("_world_environment_resource").As<Godot.Environment>();if(!owner.Get("_previous_environment_captured").AsBool()){owner.Set("_previous_environment",world.Environment!=null?Variant.From(world.Environment):default);owner.Set("_previous_environment_captured",true);}world.Environment=environment;configure_environment(owner,environment,data);}
    public void configure_environment(Node3D owner,Godot.Environment environment,Resource data){apply_environment_background(owner,environment,data);var values=data.Get("values").AsGodotDictionary();foreach(var row in Constant("ENVIRONMENT_PROPERTIES").AsGodotDictionary())if(values.TryGetValue(row.Key,out var value))environment.Set(row.Value.AsString(),value);foreach(string key in new[]{"volumetric_fog_temporal_reprojection_enabled","volumetric_fog_temporal_reprojection_amount","volumetric_fog_ambient_inject"})if(values.TryGetValue(key,out var value))environment.Set(key,value);}
    public void apply_environment_background(Node3D owner,Godot.Environment environment,Resource data)
    {
        var values=data.Get("values").AsGodotDictionary();int mode=Get(values,"background_mode",0).AsInt32();environment.Set("background_energy_multiplier",Get(values,"background_energy",1.0));if(mode==0){environment.Set("background_mode",1);environment.BackgroundColor=Get(values,"background_color",new Color("20252d")).AsColor();environment.Sky=null;return;}var sky=new Sky();if(mode==1)sky.SkyMaterial=new PanoramaSkyMaterial{Panorama=texture_for_value(owner,Get(values,"background_image",""))};else if(mode==2){var procedural=new ProceduralSkyMaterial();ApplyRows(procedural,values,Constant("PROCEDURAL_SKY_ROWS").AsGodotArray());sky.SkyMaterial=procedural;}else{var material=Resolve(owner,Get(values,"sky_material"));if(material!=null&&material.Get("type_id").AsString()=="shader_material"){sky.SkyMaterial=create_shader_material(owner,material);if(sky.SkyMaterial.GetMeta("kiwi_time_uniform","").AsString().Length>0)sky.ProcessMode=Sky.ProcessModeEnum.Realtime;}}environment.Sky=sky;environment.Set("background_mode",2);
    }
    public void restore_environment(Node3D owner){var actor=owner.Get("actor").As<Resource>();if(actor==null||actor.Get("type_id").AsString()!="world_environment"||!owner.Get("_previous_environment_captured").AsBool())return;var world=runtime_world(owner,false);if(world!=null&&world.Environment==owner.Get("_world_environment_resource").As<Godot.Environment>())world.Environment=owner.Get("_previous_environment").As<Godot.Environment>();owner.Set("_previous_environment_captured",false);}
    private static bool Growth(Node node){var script=node.GetScript().As<Script>();while(script!=null){if(script.ResourcePath=="res://Workspaces/ModelWorkspace/growth/surface_growth_instance.gd")return true;script=script.GetBaseScript();}return false;}
    public void set_timeline_time(Node3D owner,double time)
    {
        var content=Content(owner);if(content!=null)_naturalRender.time(content,time,new Settings());if(content is FogVolume){var actor=Actor(owner);double local=actor.Get("animation_time").AsDouble();if(double.IsNaN(local))local=time;_fogMotion.procedural(owner,_animation.sampled_values(actor,local),local);}foreach(var node in owner.FindChildren("*","MeshInstance3D",true,false))if(Growth(node))_growthInstances.set_growth_time((MeshInstance3D)node,time);void SetTime(ShaderMaterial? material,bool requireShader){if(material==null||requireShader&&material.Shader==null)return;string uniform=material.GetMeta("kiwi_time_uniform","").AsString();if(uniform.Length>0)material.SetShaderParameter(uniform,time);}foreach(string key in new[]{"shader_material","camera_shader_material","fog_shader_material"})SetTime(owner.Get(key).As<ShaderMaterial>(),true);var environment=owner.Get("_world_environment_resource").As<Godot.Environment>();SetTime(environment?.Sky?.SkyMaterial as ShaderMaterial,false);
    }
}
